#!/bin/sh
# morpheus:poll-guard:v1
# Generated by `morpheus context install`; edits are overwritten.
# Runs before every Bash call in Claude Code and Codex. Refuses the third
# `gh run view|run watch|pr checks` of one target in a session and prints the
# `morpheus wait-ci` command that replaces the loop. MORPHEUS_POLL_GUARD=off
# in the agent's environment disables it.
set -u
[ "${MORPHEUS_POLL_GUARD:-}" = "off" ] && exit 0
input=$(cat)
case "$input" in
  *'gh '*'run view'*|*'gh '*'run watch'*|*'gh '*'pr checks'*) ;;
  *) exit 0 ;;
esac
PATH="${PATH:-/usr/bin:/bin}:${HOME:-/nonexistent}/.local/bin:/opt/homebrew/bin:/usr/local/bin"
export PATH
command -v morpheus >/dev/null 2>&1 || exit 0
reason=$(printf '%s\n' "$input" | morpheus poll-guard 2>&1)
code=$?
if [ "$code" -eq 2 ]; then
  printf '%s\n' "$reason" >&2
  exit 2
fi
exit 0
